CLib3MF4EOSBaseClass::CLib3MF4EOSBaseClass()
		: node::ObjectWrap()
{

}

void CLib3MF4EOSBaseClass::RaiseError(v8::Isolate * isolate, std::string Message)
{
		if (isolate != nullptr) {
				isolate->ThrowException(Exception::TypeError(
						String::NewFromUtf8(isolate, Message.c_str() )));
		}
}
void CLib3MF4EOSBaseClass::CheckError(v8::Isolate * isolate, sLib3MF4EOSDynamicWrapperTable * sWrapperTable, Lib3MF4EOSHandle pInstance, Lib3MF4EOSResult errorCode)
{
		if (errorCode != 0) {
			std::string sMessage;
			if ((sWrapperTable != nullptr) && (pInstance != nullptr)) {
				if (sWrapperTable->m_GetLastError != nullptr) {
					uint32_t neededChars = 0;
					bool hasLastError = 0;
					if (sWrapperTable->m_GetLastError(pInstance, 0, &neededChars, nullptr, &hasLastError) == 0) {
						uint32_t dummyChars = 0;
						std::vector<char> Buffer;
						Buffer.resize(neededChars + 2);
						if (sWrapperTable->m_GetLastError(pInstance, neededChars + 1, &dummyChars, Buffer.data(), &hasLastError) == 0) {
							Buffer[neededChars + 1] = 0;
							sMessage = std::string(": ") + std::string(&Buffer[0]);
						}
					}
				}
			}
			throw std::runtime_error("Lib3MF4EOS Error" + sMessage + " (" + std::to_string(errorCode) + ")");
		}
}

void CLib3MF4EOSBaseClass::setHandle(Lib3MF4EOSHandle pHandle)
{
		
}

Lib3MF4EOSHandle CLib3MF4EOSBaseClass::getHandle(v8::Local<v8::Object> objecthandle)
{
		auto Field = objecthandle->GetInternalField(NODEWRAPPER_HANDLEINDEX);
		v8::Local<v8::External> externalField = Field.As<v8::External>();
		return (Lib3MF4EOSHandle *) externalField->Value();
}

sLib3MF4EOSDynamicWrapperTable * CLib3MF4EOSBaseClass::getDynamicWrapperTable(v8::Local<v8::Object> objecthandle)
{
		auto Field = objecthandle->GetInternalField(NODEWRAPPER_TABLEINDEX);
		v8::Local<v8::External> externalField = Field.As<v8::External>();
		return (sLib3MF4EOSDynamicWrapperTable *) externalField->Value();
}


